type Expr = { kind: "lit"; v: number } | { kind: "add"; l: Expr; r: Expr };
const evalExpr = (e: Expr): number => {
  switch (e.kind) {
    case "lit": return e.v;
    case "add": return evalExpr(e.l) + evalExpr(e.r);
    default: { const never: never = e; return never; }   // exhaustiveness check
  }
};

